// === Tab: mySketch ===
class Particle {
	constructor(xPos, yPos) {
		this.xPos = xPos;
		this.yPos = yPos;
		this.diam = random(2);
		this.maxDiam = 5;
		this.dead = false;
	}
	alive(speed) {
		if (this.diam < this.maxDiam ) {
			this.xPos += random(-speed, +speed);
			if (this.yPos > -width*.25){
				this.yPos -= random(speed);
			} else {
				this.yPos += random(0.1, 0.1);
			}
			push();
				stroke(255, 255, 200);
				strokeWeight(1);
				fill(255, 255, 200, 100);
				translate(width/2, height/2);
				ellipse(this.xPos, this.yPos, this.diam);
			pop();
			this.diam += 0.01;
		} else {
			this.dead = true;
		}
	}
}

const foamParticles = 200;
let foam = [];

coords = [];
let circx, circy;
const radius = 200;

function setup() {
	createCanvas(windowWidth, windowHeight);
	angleMode(DEGREES);

	for (let a = 0; a < 360; a++) {
		circx = sin(a) * radius;
		circy = cos(a) * radius;
		coords.push({x: circx, y: circy});
	}

	for (let i=0; i < foamParticles; i++){
		foam[i] = new Particle( random(coords[Math.round(random(coords.length-1))].x), random(coords[Math.round(random(coords.length-1))].y) );
	}
}

function draw() {
	background(25, 0, 0);
	for (const foamParticle of foam){
		foamParticle.alive(random(1,10));
		if (foamParticle.dead) {
			foam.splice(foamParticle, 1);
		}
	}
}

function mouseClicked() {
	for (let i=0; i < 100; i++){
		foam.push( new Particle( random(coords[Math.round(random(coords.length-1))].x), random(coords[Math.round(random(coords.length-1))].y) ) );
	}
}

